UPDATE bm_plan_template t1 SET confirmed = true WHERE t1.id IN ( SELECT t2.plan_template_id FROM bm_plan_template_batch t2 JOIN bm_process t3 ON t2.process_id = t3.id WHERE t2.is_deleted = 0 and t2.plan_template_id IN
#{id}
GROUP BY t2.plan_template_id HAVING COUNT(DISTINCT t2.process_version) = 1 AND MAX(t2.process_version) = MAX(t3.active_version) );
